  row={k:s[k] for k in ('id','task','selector','repeat','stage','recipient','donor')};row.update(direction=s['donor']+'->'+s['recipient'],selected_bytes=s['audit']['selected_bytes'],changed_bytes=s['audit']['changed_bytes'],mixed_state_sha256=s['audit']['mixed_sha256'],recipient_state_sha256=s['audit']['recipient_sha256'],donor_state_sha256=s['audit']['donor_sha256'],recipient_logits_sha256=donors[s['task']+'|'+s['recipient']]['logits']['sha256'],value_layout=s['audit']['value_layout'],metadata_unchanged=s['audit']['metadata_unchanged'],actual_changed_bytes=None,endpoint_class=None,confidence='NONE',status=receipt['status'] if receipt else 'NOT_STARTED',historical_recipient_endpoint=own,historical_donor_endpoint=donor,historical_full_KV_cross_endpoint=full,endpoint_ids=None)
